#![allow(unused)]
verus! {
    /// Given two `Vec<u32>` of equal length n ≤ 100,
    /// with each pointwise product < 1000, build a new Vec
    /// containing the pointwise products.
    #[verifier(external)]  // body is just for proof; not for execution
    fn product(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32>
        // pre‐conditions
        requires
            a.len() == b.len(),
            a.len() <= 100,
            // for every valid index, the product is < 1000
            forall |i: usize|  i < a.len() ==> a[i] * b[i] < 1000
        // post‐conditions
        ensures |c: Vec<u32>|
            c.len() == a.len()
            &&
            // each entry of c is indeed the product
            forall |i: usize| i < a.len() ==> c[i] == a[i] * b[i]
    {
        // proof sketch using a while‐loop
        let mut c: Vec<u32> = Vec::new();
        let mut i: usize = 0;

        while i < a.len() {
            //––––– Loop Invariant –––––
            //  1) 0 ≤ i ≤ a.len()
            //  2) we have already produced exactly i elements
            //     in c
            //  3) each of those i elements is the correct product
            invariant 0 <= i && i <= a.len();
            invariant c.len() == i;
            invariant forall |j: usize|
                j < i ==> c[j] == a[j] * b[j];
            //––––– Decreases –––––
            decreases a.len() - i;

            // verify the bound again
            let prod: u32 = a[i] * b[i];
            assert(prod < 1000);

            c.push(prod);
            i += 1;
        }

        // at this point i == a.len() and c.len() == i,
        // so c.len() == a.len(), and the loop invariant
        // already establishes the post‐condition
        c
    }
}